async def act(page):
    """
    From the current admin Dashboard, navigate to the Sales > Shipping report page,
    set From = 08/05/2022 and To = 03/01/2023, generate the report, and attempt to
    export it (CSV) as the final action. Export (which may navigate or download)
    is performed last.

    Notes about knowledge-base helpers (explicit utility reasoning provided in the
    accompanying step_by_step_reasoning): none of the KB helpers correspond to
    the Sales > Shipping report flow, so none are called.
    """
    # Relative navigation to the Shipping report (idempotent)
    await page.goto('/index.php/admin/report/sales_shipping/shipping/')
    await page.wait_for_load_state('domcontentloaded')
    # short pause for scripts/UI
    await page.wait_for_timeout(600)

    # Target date strings
    from_date = "08/05/2022"
    to_date = "03/01/2023"

    # Helper to try filling a labeled control using multiple label variants
    async def try_fill(labels, value):
        for lbl in labels:
            try:
                locator = page.get_by_label(lbl)
                if await locator.count() > 0:
                    await locator.fill(value)
                    return True
            except Exception:
                # transient issue or label not present; try next variant
                continue
        return False

    from_labels = ["From", "From:", "from", "Start Date", "Start"]
    to_labels = ["To", "To:", "to", "End Date", "End"]

    # Fill the date fields (robust to small label variations)
    await try_fill(from_labels, from_date)
    await try_fill(to_labels, to_date)

    # Allow any datepickers to settle
    await page.wait_for_timeout(400)

    # Preferred: click a button scoped to the form that contains the 'From' input
    clicked_generate = False
    candidate_buttons = ["Show Report", "Show", "Refresh", "Filter", "Submit", "Apply", "Go"]

    try:
        forms = page.get_by_role("form")
        if await forms.count() > 0:
            # Scope to the form that contains the 'From' labelled control
            form_with_from = forms.filter(has=page.get_by_label("From"))
            if await form_with_from.count() == 0:
                # fallback to lowercase label locator
                form_with_from = forms.filter(has=page.get_by_label("from"))

            if await form_with_from.count() > 0:
                for name in candidate_buttons:
                    btn = form_with_from.get_by_role("button", name=name)
                    if await btn.count() > 0:
                        await btn.click()
                        clicked_generate = True
                        break
    except Exception:
        clicked_generate = False

    # Global fallback: try buttons with likely names anywhere on the page
    if not clicked_generate:
        for name in candidate_buttons:
            try:
                btn = page.get_by_role("button", name=name)
                if await btn.count() > 0:
                    await btn.click()
                    clicked_generate = True
                    break
            except Exception:
                continue

    # Additional fallback: scan all buttons and click first one whose text contains keywords
    if not clicked_generate:
        try:
            buttons = page.get_by_role("button")
            if await buttons.count() > 0:
                total = await buttons.count()
                for i in range(total):
                    b = buttons.nth(i)
                    try:
                        text = (await b.inner_text()).strip()
                    except Exception:
                        text = ""
                    if text and ("report" in text.lower() or "filter" in text.lower() or "show" in text.lower()):
                        await b.click()
                        clicked_generate = True
                        break
        except Exception:
            pass

    # Wait briefly for the report to generate / UI update
    await page.wait_for_timeout(1200)

    # Try to export the report as CSV (last action)
    export_labels = ["Export to CSV", "Export CSV", "Export", "CSV", "Download CSV"]
    exported = False

    for lbl in export_labels:
        try:
            link = page.get_by_role("link", name=lbl)
            if await link.count() > 0:
                await link.click()
                exported = True
                break
        except Exception:
            pass
        try:
            btn = page.get_by_role("button", name=lbl)
            if await btn.count() > 0:
                await btn.click()
                exported = True
                break
        except Exception:
            pass

    # Conservative fallback: click the first link/button that contains 'csv' in its visible text
    if not exported:
        try:
            links = page.get_by_role("link")
            if await links.count() > 0:
                total = await links.count()
                for i in range(total):
                    l = links.nth(i)
                    try:
                        name = (await l.inner_text()).strip()
                    except Exception:
                        name = ""
                    if name and 'csv' in name.lower():
                        await l.click()
                        exported = True
                        break
        except Exception:
            pass

    if not exported:
        try:
            buttons = page.get_by_role("button")
            if await buttons.count() > 0:
                total = await buttons.count()
                for i in range(total):
                    b = buttons.nth(i)
                    try:
                        name = (await b.inner_text()).strip()
                    except Exception:
                        name = ""
                    if name and 'csv' in name.lower():
                        await b.click()
                        exported = True
                        break
        except Exception:
            pass

    # Completed actions: either exported (final action) or report generated in-page.
    return

